const CACHE='modular-ai-shell-v2';const SHELL=['./','./index.html','./style.css','./app.js','./chat.js','./engine.js','./router.js','./worker.js','./manifest.json'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||!SHELL.some(p=>new URL(p,self.location.href).href===e.request.url))return;e.respondWith(fetch(e.request).catch(()=>caches.open(CACHE).then(c=>c.match(e.request))));});
